import { graphql, navigate } from "gatsby";
import React from "react";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import { useAuth } from "../../features/auth/AuthContext";

export default function AdminDashboard() {
  const { user, role, signOut } = useAuth();

  async function handleSignOut() {
    await signOut();
    navigate("/login");
  }

  return (
    <AdminLayout title="Dashboard">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <DashboardCard
          label="Users"
          description="Manage customers and agents."
          onClick={() => navigate("/admin/users")}
        />
        <DashboardCard
          label="Itineraries"
          description="Create and manage travel itineraries."
          onClick={() => navigate("/admin/itineraries")}
        />
        <DashboardCard
          label="Support notes"
          description="Internal follow-up notes."
          onClick={() => navigate("/admin/support")}
        />
        <DashboardCard
          label="Audit log"
          description="Track all changes in the system."
          onClick={() => navigate("/admin/audit")}
        />
        <DashboardCard
          label="Cost & Price Report"
          description="View activity costs and prices per customer."
          onClick={() => navigate("/admin/report")}
        />
      </div>

      <div className="mt-8 flex items-center justify-between">
        <p className="text-xs text-gray-400">
          Signed in as {user?.email} &nbsp;·&nbsp; role: <strong>{role ?? "null"}</strong>
        </p>
        <button
          onClick={handleSignOut}
          className="rounded-lg border border-gray-200 px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-100"
        >
          Sign out
        </button>
      </div>
    </AdminLayout>
  );
}

function DashboardCard({
  label,
  description,
  onClick,
}: {
  label: string;
  description: string;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="rounded-xl bg-white p-5 text-left shadow-sm ring-1 ring-gray-200 transition hover:ring-gray-400"
    >
      <p className="font-semibold text-gray-900">{label}</p>
      <p className="mt-1 text-sm text-gray-500">{description}</p>
    </button>
  );
}
export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;